from typing import NoReturn

import pytest


class DivZero(Exception):
    """Raised when safe_div is asked to divide by zero."""

    def __init__(self, a: int) -> None:
        super().__init__(a)
        self.a: int = a


def safe_div(a: int, b: int) -> int:
    """Return a // b using integer floor division.

    Raises DivZero carrying the numerator a when b is zero.
    """
    if b == 0:
        raise DivZero(a)
    return a // b


def test_safe_div_exact() -> None:
    assert safe_div(10, 2) == 5


def test_safe_div_truncates_positive() -> None:
    assert safe_div(7, 2) == 3


def test_safe_div_floors_negative_numerator() -> None:
    assert safe_div(-7, 2) == -4


def test_safe_div_negative_divisor() -> None:
    assert safe_div(7, -2) == -4


def test_safe_div_zero_numerator() -> None:
    assert safe_div(0, 5) == 0


def test_safe_div_by_zero_raises_with_numerator() -> None:
    with pytest.raises(DivZero) as excinfo:
        safe_div(42, 0)
    assert excinfo.value.a == 42


def test_safe_div_by_zero_negative_numerator() -> None:
    with pytest.raises(DivZero) as excinfo:
        safe_div(-3, 0)
    assert excinfo.value.a == -3
